[ExtensionOf(classStr(SmmUpdateBusRel))]
final class AVASmmUpdateBusRel_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_custTable">CustTable</param>
/// <param name = "_smmBusRelTable">smmBusRelTable</param>
public void updateFromCustTableSFA2(CustTable _custTable, smmBusRelTable _smmBusRelTable)
{
    smmBusRelTable      smmBusRelTable;

    if (_smmBusRelTable)
    {
        smmBusRelTable = _smmBusRelTable;
    }
    else
    {
        smmBusRelTable = smmBusRelTable::findByParty(_custTable.Party, true);
    }
    if (smmBusRelTable)
    {

        smmBusRelTable.KCS_LimitGroupName = _custTable.KCS_LimitGroupName;
        smmBusRelTable.KCS_MaxBonusAmount = _custTable.KCS_MaxBonusAmount;
        smmBusRelTable.KCS_SalesGroup     = _custTable.SalesGroup;
        smmBusRelTable.KCS_CRMPaymMode    = _custTable.PaymMode;
        smmBusRelTable.KCS_CRMPaymTermId  = _custTable.PaymTermId;
        smmBusRelTable.KCS_CRMCashDisc    = _custTable.CashDisc;
    }
    next updateFromCustTableSFA2(_custTable,smmBusRelTable);
}
